<?php use App\Support\View; ?>
<main id="conteudo" class="content report-page"><header class="topbar"><div><span class="eyebrow">Súmula digital · versão <?=View::e($match['report_version']??'1')?></span><h1><?=View::e($match['home_name'])?> <span class="score"><?=$match['home_score']?> × <?=$match['away_score']?></span> <?=View::e($match['away_name'])?></h1><p class="muted"><?=View::e($match['tournament_name'])?> · <?=View::e($match['stage_name']??'')?> · <?=View::e($match['round_name']??'')?></p></div><a class="button ghost" href="/admin/tournaments/<?=$match['tournament_id']?>/operation#partidas">Voltar à operação</a></header><section class="panel"><div class="panel-head"><h2>Conferência para homologação</h2><span class="status"><?=View::e($match['status'])?></span></div><dl class="report-meta"><div><dt>Data</dt><dd><?=View::e($match['scheduled_at']??'A definir')?></dd></div><div><dt>Grupo</dt><dd><?=View::e($match['group_name']??'—')?></dd></div><div><dt>Escalações</dt><dd><?=count($lineups)?></dd></div><div><dt>Eventos</dt><dd><?=count($events)?></dd></div></dl></section><section class="panel"><h2>Escalações</h2><div class="table-wrap"><table><thead><tr><th>Equipe</th><th>Atleta</th><th>Função</th><th>Número</th><th>Capitão</th><th>Goleiro</th></tr></thead><tbody><?php foreach($lineups as $l):?><tr><td><?=View::e($l['team_name'])?></td><td><?=View::e($l['full_name'])?></td><td><?=View::e($l['lineup_role'])?></td><td><?=View::e($l['shirt_number'])?></td><td><?=$l['is_captain']?'Sim':'Não'?></td><td><?=$l['is_goalkeeper']?'Sim':'Não'?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Cronologia da partida</h2><ol class="event-timeline"><?php foreach($events as $e):?><li><time><?=View::e($e['minute']??'—')?>'</time><div><strong><?=View::e($e['event_type'])?><?=$e['is_cancelled']?' · anulado':''?></strong><span><?=View::e($e['team_name']??'—')?> · <?=View::e($e['full_name']??'Sem atleta')?></span></div><small><?=View::e($e['period']??'—')?></small></li><?php 